void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec4 tracking = vrchSampleSignalTexture(0, uv);
  float confidence = vrchReadSignal(0);
  float motion = vrchReadSignal(1);
  float pointDensity = clamp(float(uParam_point_count - 4) / 30.0, 0.0, 1.0);
  float contourEdge = 0.92 - clamp(uParam_line_width, 0.0, 2.0) * 0.02;
  float nodeEdge = 0.92 - clamp(uParam_node_size, 0.0, 2.0) * 0.02 - pointDensity * 0.005;
  float contours = step(0.001, uParam_line_width) * smoothstep(0.02, contourEdge, tracking.r);
  float nodes = step(0.001, uParam_node_size) * smoothstep(0.02, nodeEdge, tracking.g);
  float trails = step(0.001, uParam_trail_width) * step(0.001, uParam_trail_length) * smoothstep(0.01, 0.9, tracking.b);
  float shape = clamp(max(contours, nodes) + trails * 0.7, 0.0, 1.0);
  float glow = clamp(tracking.a * (uParam_glow + motion * 0.18) * step(0.001, shape), 0.0, 1.0);
  vec3 background = mix(uParam_background_color.rgb, vrchSampleSource0(uv).rgb, clamp(uParam_background_image, 0.0, 1.0));
  vec3 trackerColor = uParam_color.rgb * (shape + glow * 0.35) * mix(0.45, 1.0, confidence);
  fragColor = vec4(background + trackerColor, 1.0);
}
